// GERADO por um script (ver o commit da etapa 3): ícones Phosphor (MIT) usados na página inicial, só nos pesos
// regular, bold e fill. O pacote @phosphor-icons/react traz os 6 pesos de cada ícone no JavaScript; aqui cada ícone
// leva só o que a landing usa. Mesma API básica: size, weight, color, className, style.
import type { CSSProperties } from 'react'

type Weight = 'regular' | 'bold' | 'fill'
export type IconProps = { size?: number | string; weight?: Weight; color?: string; className?: string; style?: CSSProperties; 'aria-hidden'?: boolean | 'true' | 'false' }
export type Icon = (props: IconProps) => JSX.Element

type Paths = Record<Weight, string>

// Cada ícone é um export próprio, marcado como puro: o bundler descarta os que uma ilha não usa.
function make(name: string, paths: Paths): Icon {
  function PhIcon({ size = '1em', weight = 'regular', color = 'currentColor', className, style, ...rest }: IconProps) {
    return (
      <svg
        xmlns="http://www.w3.org/2000/svg"
        width={size}
        height={size}
        viewBox="0 0 256 256"
        fill={color}
        className={className}
        style={style}
        aria-hidden={rest['aria-hidden'] ?? true}
        focusable="false"
        dangerouslySetInnerHTML={{ __html: paths[weight] }}
      />
    )
  }
  PhIcon.displayName = name
  return PhIcon
}

